def searchSortedGrid(grid, target):
    m, n = len(grid), len(grid[0])
    row, col = 0, n - 1
    while row < m and col >= 0:
        v = grid[row][col]
        if v == target:
            return True
        if v > target:
            col -= 1
        else:
            row += 1
    return False
